// Generates docs/build/data-model.html — the stored schema as built — from
// packages/db/src/schema, deterministically, so CI can prove the visual is
// current instead of trusting that somebody regenerated it.
//
// Why this exists: the previous data-model.html was hand-generated by an agent
// session at migration 0030 and then sat still while the schema moved to 0039
// — nine migrations stale, which is precisely the failure a derived view
// invites when a human is the regeneration step. This script IS the
// regeneration step: `--write` emits the file, `--check` regenerates to memory
// and fails if the committed file differs, and `pnpm run check` runs the check.
//
// What it derives, and from where:
//   - tables, columns, types, nullability, defaults, PKs — drizzle
//     getTableConfig() over every exported pgTable, drawer module by drawer
//     module (the module IS the drawer)
//   - foreign keys — the same config, rendered as "→ table.column"
//   - integrity badges (append-only, interval rows, frozen at issue,
//     immutable from ready, one-way binding) — the migration SQL, scanned for
//     CREATE TRIGGER, because triggers live in hand-written migrations and
//     nowhere in the drizzle schema
//
// The output is a self-contained atlas: no build step, no network, open in a
// browser. The previous hand-crafted pan/zoom ontology graph is deliberately
// not reproduced — a generated-but-wrong diagram would cost more than a
// missing one; the FK annotations carry the same information per table.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { getTableConfig, PgTable } from 'drizzle-orm/pg-core';

import * as drawer1 from '../src/schema/drawer1-parties';
import * as drawer2 from '../src/schema/drawer2-documents';
import * as drawer3 from '../src/schema/drawer3-execution';
import * as drawer4 from '../src/schema/drawer4-output';
import * as drawer5 from '../src/schema/drawer5-review';
import * as drawer6 from '../src/schema/drawer6-ontology';
import * as drawer7 from '../src/schema/drawer7-context';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..', '..', '..');
const outPath = join(repoRoot, 'docs/build/data-model.html');

const DRAWERS: Array<{ key: string; title: string; blurb: string; module: Record<string, unknown> }> = [
  { key: 'd1', title: 'Drawer 1 — Parties & access', blurb: 'Who exists, and who may see what. Every other table is scoped by these.', module: drawer1 },
  { key: 'd2', title: 'Drawer 2 — Documents', blurb: 'The controlled record and the working area: containers, immutable versions, the retrieval index, the sandbox.', module: drawer2 },
  { key: 'd3', title: 'Drawer 3 — Work & execution', blurb: 'Work items, conversations, the append-only Run/Step record, the plan artefact.', module: drawer3 },
  { key: 'd4', title: 'Drawer 4 — AI output & feedback', blurb: 'Suggestions, citations, and the Signal each resolution writes.', module: drawer4 },
  { key: 'd5', title: 'Drawer 5 — Review', blurb: 'The review cycle at two scopes: cycles, rounds, transmittals, comments, responses, appointments and shares.', module: drawer5 },
  { key: 'd6', title: 'Drawer 6 — The project ontology', blurb: 'The classification vocabulary and the typed edges between containers.', module: drawer6 },
  { key: 'd7', title: 'Drawer 7 — Context', blurb: 'The scoped context stores (ADR-0020). Org context only so far: the firm’s rulebook and its verbatim clauses (T-308, ADR-0048).', module: drawer7 },
];

// The atlas is only "the schema as built" while this list is complete, and the
// list is hand-typed: drawer 7 shipped (T-308) without joining it, and
// `--check` could not notice because it compares the committed file against
// this generator's own output — both agreed, both were missing the drawer. So
// completeness is asserted against the directory: a schema drawer file with no
// DRAWERS entry kills the run, in --check and --write alike.
const schemaDir = join(here, '..', 'src', 'schema');
const drawerFiles = readdirSync(schemaDir).filter((f) => /^drawer\d+-.*\.ts$/.test(f));
if (drawerFiles.length !== DRAWERS.length) {
  console.error(
    `generate-data-model.ts: ${schemaDir} holds ${drawerFiles.length} drawer modules ` +
      `(${drawerFiles.sort().join(', ')}) but DRAWERS lists ${DRAWERS.length}. ` +
      `Add the missing drawer's import and entry above, then regenerate ` +
      `(pnpm --filter @infora/db run datamodel).`,
  );
  process.exit(1);
}

// ---- integrity badges from the migration triggers -------------------------
const BADGE_LABELS: Array<[RegExp, string]> = [
  [/append_only$/, 'append-only'],
  [/_interval$/, 'interval rows'],
  [/_frozen$/, 'frozen at issue'],
  [/immutable_from_ready$/, 'immutable from ready'],
  [/immutable_content$/, 'immutable content'],
  [/one_way$/, 'one-way transition'],
];

function triggerBadges(): Map<string, Set<string>> {
  const badges = new Map<string, Set<string>>();
  const migrationsDir = join(here, '..', 'migrations');
  for (const file of readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort()) {
    const sql = readFileSync(join(migrationsDir, file), 'utf8');
    for (const m of sql.matchAll(/CREATE TRIGGER\s+"?(\w+)"?[\s\S]{0,200}?ON\s+"?(\w+)"?/g)) {
      const [, trigger, table] = m;
      for (const [pattern, label] of BADGE_LABELS) {
        if (!pattern.test(trigger!)) continue;
        if (!badges.has(table!)) badges.set(table!, new Set());
        badges.get(table!)!.add(label);
      }
    }
  }
  return badges;
}

// ---- schema introspection -------------------------------------------------
type ColumnRow = { name: string; type: string; notes: string[] };
type TableCard = { name: string; columns: ColumnRow[]; badges: string[] };

function esc(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function tableCards(module: Record<string, unknown>, badges: Map<string, Set<string>>): TableCard[] {
  const cards: TableCard[] = [];
  for (const value of Object.values(module)) {
    if (!(value instanceof PgTable)) continue;
    const config = getTableConfig(value);

    // FK targets per local column name
    const fkOf = new Map<string, string>();
    for (const fk of config.foreignKeys) {
      const ref = fk.reference();
      ref.columns.forEach((column, i) => {
        const foreign = ref.foreignColumns[i]!;
        fkOf.set(column.name, `${getTableConfig(foreign.table as PgTable).name}.${foreign.name}`);
      });
    }

    const columns: ColumnRow[] = config.columns.map((column) => {
      const notes: string[] = [];
      if (column.primary) notes.push('PK');
      const fk = fkOf.get(column.name);
      if (fk) notes.push(`→ ${fk}`);
      if (!column.notNull && !column.primary) notes.push('nullable');
      if (column.hasDefault) notes.push('default');
      return { name: column.name, type: column.getSQLType(), notes };
    });

    cards.push({
      name: config.name,
      columns,
      badges: [...(badges.get(config.name) ?? [])].sort(),
    });
  }
  return cards;
}

// ---- render ---------------------------------------------------------------
function render(): string {
  const badges = triggerBadges();
  const sections = DRAWERS.map(({ key, title, blurb, module }) => {
    const cards = tableCards(module, badges)
      .map(
        (t) => `      <article class="card ${key}">
        <h3>${esc(t.name)}${t.badges.map((b) => ` <span class="badge">${esc(b)}</span>`).join('')}</h3>
        <table><tbody>
${t.columns
  .map(
    (c) =>
      `          <tr><td class="col">${esc(c.name)}</td><td class="type">${esc(c.type)}</td><td class="notes">${esc(c.notes.join(' · '))}</td></tr>`,
  )
  .join('\n')}
        </tbody></table>
      </article>`,
      )
      .join('\n');
    return `    <section class="drawer ${key}">
      <h2>${esc(title)}</h2>
      <p class="blurb">${esc(blurb)}</p>
${cards}
    </section>`;
  }).join('\n');

  return `<!--
  GENERATED FILE — do not edit by hand.
  Emitted by packages/db/scripts/generate-data-model.ts from
  packages/db/src/schema (tables, columns, FKs) and packages/db/migrations
  (trigger-derived integrity badges). Regenerate with
      pnpm --filter @infora/db run datamodel
  \`pnpm run check\` fails when this file is stale (check:data-model), so the
  atlas can no longer sit nine migrations behind the schema the way the
  hand-generated version did. data-model.md holds the narrative and the design
  decisions; this file is the shape, as built.
-->
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Infora — the data model, as built</title>
<style>
  :root {
    --ground: #F4F6F7; --card: #FFFFFF; --ink: #1C2733; --ink-soft: #55636F;
    --line: #D8DFE3;
    --d1: #3E5C76; --d2: #2E7D5B; --d3: #A9721F; --d4: #68579E; --d5: #A8453C; --d6: #3C7A82;
  }
  * { box-sizing: border-box; }
  body { margin: 0; padding: 2rem; background: var(--ground); color: var(--ink);
         font: 14px/1.45 -apple-system, "Segoe UI", Roboto, sans-serif; }
  h1 { font-size: 1.3rem; margin: 0 0 .25rem; }
  p.note { color: var(--ink-soft); margin: 0 0 1.5rem; max-width: 60rem; }
  section.drawer { margin: 0 0 2rem; }
  section.drawer > h2 { font-size: 1.05rem; border-bottom: 2px solid var(--line);
                        padding-bottom: .3rem; }
  .d1 > h2 { border-color: var(--d1); } .d2 > h2 { border-color: var(--d2); }
  .d3 > h2 { border-color: var(--d3); } .d4 > h2 { border-color: var(--d4); }
  .d5 > h2 { border-color: var(--d5); } .d6 > h2 { border-color: var(--d6); }
  p.blurb { color: var(--ink-soft); margin: .25rem 0 1rem; }
  section.drawer { display: block; }
  .card { display: inline-block; vertical-align: top; background: var(--card);
          border: 1px solid var(--line); border-radius: 8px; padding: .75rem 1rem;
          margin: 0 1rem 1rem 0; min-width: 20rem; }
  .card h3 { margin: 0 0 .5rem; font-size: .95rem; font-family: ui-monospace, monospace; }
  .card.d1 h3 { color: var(--d1); } .card.d2 h3 { color: var(--d2); }
  .card.d3 h3 { color: var(--d3); } .card.d4 h3 { color: var(--d4); }
  .card.d5 h3 { color: var(--d5); } .card.d6 h3 { color: var(--d6); }
  .badge { font: 10px/1 -apple-system, sans-serif; color: #4A5560; background: #EEF1F3;
           border: 1px solid var(--line); border-radius: 999px; padding: 2px 8px;
           vertical-align: middle; }
  .card table { border-collapse: collapse; }
  .card td { padding: 1px 10px 1px 0; font-family: ui-monospace, monospace; font-size: 12px; }
  td.type { color: var(--ink-soft); }
  td.notes { color: var(--ink-soft); font-family: -apple-system, sans-serif; font-size: 11px; }
</style>
</head>
<body>
  <h1>Infora — the data model, as built</h1>
  <p class="note">Generated from <code>packages/db/src/schema</code>; integrity badges
  from the migration triggers. The narrative and the design decisions live in
  <code>docs/build/data-model.md</code>; this page is the shape.</p>
${sections}
</body>
</html>
`;
}

// ---- write / check --------------------------------------------------------
const mode = process.argv.includes('--check') ? 'check' : 'write';
const html = render();

if (mode === 'write') {
  writeFileSync(outPath, html);
  console.log(`wrote ${outPath}`);
} else {
  let committed = '';
  try {
    committed = readFileSync(outPath, 'utf8');
  } catch {
    // missing counts as stale
  }
  if (committed !== html) {
    console.error(
      'docs/build/data-model.html is stale against packages/db/src/schema.\n' +
        'Regenerate it:  pnpm --filter @infora/db run datamodel',
    );
    process.exit(1);
  }
  console.log('data-model.html is current with the schema.');
}
